using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF 9 changed discriminator from "Discriminator" to "$type".
            // Keep the old property name so existing 500K documents remain readable.
            entity.HasDiscriminator<string>("Discriminator");

            // EF 9 changed id format from "EntityType|Key" to just "Key".
            // Preserve the EF 8 format so existing ids like "Product|123" still resolve.
            entity.HasKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyCosmosIdGenerator>();
        });

        // HasIndex() was silently ignored by the Cosmos provider in EF 8;
        // in EF 9 it throws. Removed.
    }
}
